using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Grasshopper.Kernel;

namespace BenchPlugin
{
    public class AsyncStatsComponent : GH_Component
    {
        private CancellationTokenSource _cts;
        private Task<double[]> _task;
        private double[] _result;

        public AsyncStatsComponent()
            : base("Async Stats", "AStats", "Computes mean and standard deviation of a list of numbers asynchronously", "Bench", "Data")
        {
        }

        public override Guid ComponentGuid => new Guid("f6c1a8e9-3d47-4c5a-91b2-8d5e0f4a2c46");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddNumberParameter("Values", "V", "Numbers to analyse", GH_ParamAccess.list);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddNumberParameter("Mean", "M", "Arithmetic mean", GH_ParamAccess.item);
            pManager.AddNumberParameter("StdDev", "SD", "Population standard deviation", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            // Second pass, triggered by the finished task: publish the result.
            if (_result != null)
            {
                double[] result = _result;
                _result = null;
                _task = null;
                DA.SetData(0, result[0]);
                DA.SetData(1, result[1]);
                return;
            }

            var values = new List<double>();
            if (!DA.GetDataList(0, values)) return;
            if (values.Count == 0)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Warning, "Values is empty");
                return;
            }

            // Inputs changed: cancel the previous computation and start anew.
            _cts?.Cancel();
            _cts?.Dispose();
            var cts = new CancellationTokenSource();
            _cts = cts;
            double[] data = values.ToArray();

            Task<double[]> task = Task.Run(() => Compute(data, cts.Token), cts.Token);
            _task = task;
            task.ContinueWith(t =>
            {
                if (t.IsCanceled || t.IsFaulted || !ReferenceEquals(_task, t)) return;
                _result = t.Result;
                Grasshopper.Instances.DocumentEditor?.BeginInvoke((Action)(() => ExpireSolution(true)));
            }, TaskScheduler.Default);

            Message = "Computing...";
        }

        private static double[] Compute(double[] data, CancellationToken token)
        {
            double sum = 0;
            for (int i = 0; i < data.Length; i++)
            {
                if ((i & 0xFFFF) == 0) token.ThrowIfCancellationRequested();
                sum += data[i];
            }
            double mean = sum / data.Length;

            double sq = 0;
            for (int i = 0; i < data.Length; i++)
            {
                if ((i & 0xFFFF) == 0) token.ThrowIfCancellationRequested();
                double d = data[i] - mean;
                sq += d * d;
            }
            return new[] { mean, Math.Sqrt(sq / data.Length) };
        }
    }
}
